insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale or Resale of Property$t$, $j$["Issued by: Borough of Audubon (requests handled by the Administrative Assistant to the Superintendent of Public Works; interior fire inspection by the Fire Marshal, exterior inspection by the Borough)","Contact: 856-547-1240 ext. 110 · k.melvin@audubonnj.com","Apply: Submit the request at least 15 business days before settlement; inspections and responses typically take 7 to 10 business days","How to apply: Only the seller or the seller's agent (attorney, agent or property manager) may request; buyers and buyers' agents cannot. Fill out the 2026 CO application (or email the seller name, property address, closing date and whether there is a sump pump) to Kristen Melvin at k.melvin@audubonnj.com. Pay with two separate payments ($50 exterior and $25 fire) by check or money order payable to Borough of Au","Valid for: 90 days from the date of issuance","Two inspections must both pass: an interior fire inspection and an exterior property inspection","Sidewalks, walkways, driveways, driveway aprons, steps and pavers must be free of cracks, raised or uneven surfaces, deterioration and trip hazards","Ramping a raised sidewalk joint is not an acceptable repair","Smoke and CO detectors must be UL listed, have a 10-year sealed battery, and be no more than 10 years old","Hardwired smoke alarms cannot be swapped for battery units; hardwired units must be interconnected and working","Smoke detector on every level (basement, each floor, and a finished or used attic) and in every bedroom","Working smoke and CO detector within 10 feet of all bedrooms","House numbers at least 4 inches tall, contrasting, visible from the street","No double-cylinder (keyed both sides) deadbolts on exit doors; exits must open from inside without a key","Sump pumps, roof drains and other discharges may not be connected to the sanitary sewer","All liens and property maintenance charges resolved and all construction permits closed before the CO is issued","Also: Open construction permits must be closed: Sellers must contact the Construction Office to make sure all permits are closed before applying: (856) 547-6312, n.bicking@audubonnj.com.","Also: Liens and property maintenance charges: All liens and outstanding property maintenance charges must be resolved before the CO is issued.","Also: Sump pump / drainage disclosure: The request must state whether there is a sump pump; sump pumps and roof drains may not discharge into the sanitary sewer."]$j$::jsonb, $j$[{"label":"Exterior property inspection","amount":"$50"},{"label":"Interior fire inspection (paid separately)","amount":"$25"},{"label":"Exterior inspection, per 2026 application form (separate check or money order)","amount":"$50.00"},{"label":"Fire inspection, per 2026 application form (separate check or money order)","amount":"$25.00"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info$t$, $j$[{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f","label":"Official source (audubonnj.com)"}]$j$::jsonb, $t$A Certificate of Occupancy (CO) is required for the sale or resale of all residential and non-residential properties in the Borough of Audubon, whether occupied or vacant.$t$, $t$84c62f49f2a77b49def0d2d04b90c2fadb0c96db62af71b967c77f1332b7cdd4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Audubon Fire Marshal's Office (town fire bureau)","Contact: 856-547-0710 ext. 117","Apply: Part of the resale CO request; submit at least 15 business days before settlement","How to apply: Requested together with the resale CO through Kristen Melvin (k.melvin@audubonnj.com, 856-547-1240 ext. 110). Pay the $25 fire fee as its own check, money order or exact cash, separate from the $50 exterior fee.","Fire official in the NJ state directory (town), updated n/a: Ernest F Busch · (856) 546-5399 · ebusch@haddonfield-nj.gov","Smoke and CO alarms must be UL listed with a 10-year sealed battery and no more than 10 years old","Hardwired smoke alarms may not be replaced with battery-only units and must be interconnected","Smoke alarm on every level including basement and a finished or used attic, plus one in every bedroom","Smoke and CO alarm within 10 feet of all bedrooms (combination units allowed)","House numbers at least 4 inches tall and visible from the street","No double-cylinder deadbolts on exit doors","Fire inspections are Thursday mornings only; someone must be present or a lockbox code provided","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Interior fire inspection (resale)","amount":"$25"},{"label":"Fire inspection, requirements sheet","amount":"$25"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/fs/resource-manager/view/683dc676-1b13-445c-9e63-e74ff15a5309$t$, $j$[{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/683dc676-1b13-445c-9e63-e74ff15a5309","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$State law requires a fire inspection before any sale, and failure to comply may result in state fines.$t$, $t$222b81cc97e9ea2040689d3d14de027aa7d2f4a5bbcce68fc0ccf41da8fdcf01$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0402$t$, $t$Audubon Park Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Audubon Park Borough requires a resale certificate. Call the office before closing.","Contact: 856-547-5236 · apclerk@audubonparknj.org"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://audubonparknj.org/$t$, $j$[]$j$::jsonb, null, $t$861ff17604ad0e6770ecb6f26964325339ea3082c1184254ce2e277daf12476e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":4,"q_ok":2,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0402.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0402.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0402$t$, $t$Audubon Park Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Township Bureau of Fire Prevention, Office of the Fire Marshal (serving Audubon Park by shared services agreement) (town fire bureau)","Contact: 856-833-6276 · rsheppard@haddontwp.com","Apply: Apply more than 14 business days before the change of occupant for the lowest fee","How to apply: Contact the Haddon Township Fire Marshal's Office, Township Annex Building, 10 Reeve Ave., Haddon Township. No Audubon Park specific application form was found.","Fire official in the NJ state directory (town), updated 5/26/2026: William A Behnke · (856) 854-1176 · wbehnke@haddontwp.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request received more than 14 business days before change of occupant","amount":"$150.00"},{"label":"Smoke/CO certificate, request received 7 to under 14 business days before change of occupant","amount":"$175.00"},{"label":"Smoke/CO certificate, request received 4 to under 7 business days before change of occupant","amount":"$200.00"},{"label":"Smoke/CO certificate, request received less than 4 days before change of occupant","amount":"$225.00"},{"label":"Smoke/CO certificate, request submitted after the change of occupant","amount":"$250"}]$j$::jsonb, null, $t$https://www.haddontwp.com/departmets/fire-marshall/$t$, $j$[{"url":"https://audubonparknj.org/ordinances/2023/Ord_2023-01.pdf","label":"Official source (audubonparknj.org)"},{"url":"https://www.haddontwp.com/departmets/fire-marshall/","label":"Official source (haddontwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The local enforcing agency shall be the Office of the Fire Marshal in the Bureau of Fire Prevention of the Township of Haddon.$t$, $t$af0799fce7ed8b097a97552b9548e1e414cbe5d886b18aed9a32f392ab06defd$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":4,"q_ok":2,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0402.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0402.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0403$t$, $t$Barrington Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Inspection on Residential Home Resales (resale CO)$t$, $j$["Issued by: Barrington Construction Department","Contact: 856-547-0706 · constructionofficial@barringtonboro.com","Apply: Apply 14 or more business days before settlement for the lowest fee","How to apply: Download and fill out the Application and Checklist for Continued Certificate of Inspection on Residential Home Resales and submit it to the Construction Department at the Borough Municipal Building, 229 Trenton Avenue. Also call Public Works (856-547-2486) to schedule the sump pump inspection and the Regional Fire Prevention Alliance (856-547-0991) for the smoke and CO inspection.","House number visible from the street, at least 4 inches tall","Sidewalks safe, no raised or deteriorated concrete","Deteriorated asphalt driveway aprons must be replaced with concrete","Handrails on steps with 3 or more risers (both sides if over 30 inches above grade); spindles no more than 4 inches apart","Porches without perimeter railings must get railings","Peeling or chipping exterior paint scraped and repainted; unpainted surfaces painted","Broken window panes repaired","Open splices or improperly installed exterior electrical fixtures corrected","Gutters and downspouts connected and in place","Any other hazardous condition the inspector finds must be corrected","Separate sump pump inspection by the Superintendent of Public Works","Separate smoke and CO detector inspection by the Regional Fire Prevention Alliance","Also: Sump pump inspection: Performed by the Superintendent of Public Works; call Mike Ciocco at 856-547-2486. Included in the $100 resale inspection fee per the Borough web page."]$j$::jsonb, $j$[{"label":"Resale CO, request received 14+ business days before settlement","amount":"$100.00"},{"label":"Resale CO, request received 13 to 6 business days before settlement","amount":"$150.00"},{"label":"Resale CO, request received 5 business days or less before settlement","amount":"$200.00"},{"label":"Each re-inspection","amount":"$50.00"},{"label":"Sump pump inspection (included in the base resale inspection fee)","amount":"$100"}]$j$::jsonb, $t$http://barringtonboro.com/wp-content/uploads/2026/05/CO-Application-1-fillable.pdf$t$, $t$https://barringtonboro.com/borough-services/construction/$t$, $j$[{"url":"https://barringtonboro.com/borough-services/construction/","label":"Official source (barringtonboro.com)"},{"url":"http://barringtonboro.com/wp-content/uploads/2026/05/CO-Application-1-fillable.pdf","label":"Official source (barringtonboro.com)"}]$j$::jsonb, $t$The Certificate of Inspection program for residential re-sales has resumed. The new CO inspection application form and explanations are now available here.$t$, $t$bd67c684b435e43ae3d1264734be251d8fe24851958f7040af06d0273e6f4068$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0403.json$t$, true),
  ($t$0403$t$, $t$Barrington Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Barrington) (town fire bureau)","Contact: 856-547-0991 · firealliance@barringtonboro.com","Apply: Apply 14 or more business days before the change of occupant for the lowest fee; weekends, holidays and the settlement date do not count","How to apply: Fill out the Alliance smoke detector certification application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox at 205 Haines Avenue, Barrington. Include a check or money order payable to 'Regional Fire Prevention Alliance'. Fees are non-refundable. Walk-in office hours are Tuesday to Friday 8 a.m. to 2 p.m.","Fire official in the NJ state directory (town), updated 9/7/2022: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; undated alarms must be replaced","Each level needs either a hardwired alarm or a 10-year sealed battery alarm; hardwired alarms must be interconnected","CO alarm within 10 feet of all sleeping areas if the home has a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Monitored low-voltage fire alarm systems must be tested by an alarm contractor before the inspection, with a copy of the certification for the inspector","House numbers: Arabic numerals at least 3 inches tall, contrasting, at least 60 inches above ground, visible from the street","Secondary power source label (for example 'CAUTION MULTIPLE SOURCES OF POWER', not handwritten) within 18 inches of the main electrical panel and meter when the home has a generator, solar panels or battery storage","Person over 18 must meet the inspector at the start of the time block","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 14+ business days before change of occupant","amount":"$66.00"},{"label":"Smoke/CO certificate, 8 to 13 business days before change of occupant","amount":"$74.00"},{"label":"Smoke/CO certificate, 4 to 7 business days before change of occupant","amount":"$106.00"},{"label":"Smoke/CO certificate, 3 business days or less before change of occupant","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$http://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"http://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$e1afb85274518708a6adf038684a8431a4b58e672c769915e3a8a5b5dc7bab04$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0403.json$t$, true),
  ($t$0404$t$, $t$Bellmawr Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Resale or Change of Ownership)$t$, $j$["Issued by: Bellmawr Construction/Zoning/Code Enforcement Office","Contact: 856-933-1286 · ConstructionOffice@Bellmawr.com","Apply: Must be obtained before settlement; application and payment are required before an inspection is scheduled (no specific number of days published)","How to apply: Fill out the Residential Certificate of Occupancy Application and bring or mail it (addressed 'Attn: Construction') to the Construction Office, 21 E. Browning Road, Bellmawr, with cash (exact) or a check payable to Borough of Bellmawr. No credit cards in the office. All taxes, grass cuts, liens and open permits must be paid or closed before the application is accepted. The office calls to schedule","Valid for: 30 days from issuance","House number visible from the street, at least 4 inches tall","Steps without trip-hazard cracks; open wood risers closed so a 4 inch ball cannot pass","Cracked sidewalk or walkway blocks with a change in elevation must be replaced","Guardrails (36 inch minimum) where porches, landings or stairs are over 30 inches above grade; handrail on steps with 4 or more risers","Yard free of high grass, weeds, debris and bamboo (unless contained per Borough code)","Grading slopes away from the foundation; gutters, downspouts and splash blocks in place","Sump pump crock must have a pump, check valve, proper outlet, and discharge outside (never to the sanitary sewer)","No signs of pests; if found, a licensed pest control certification is needed","Bathroom window or exhaust fan; GFCI protection on existing bathroom, kitchen counter, garage and exterior outlets","Electrical covers, fixtures and panel secure and labeled; A/C disconnect at the outdoor unit","Bedroom windows open easily for escape; no double-keyed deadbolts","Water heater with proper relief valve and discharge pipe to 2 to 6 inches above the floor; no leaks","Heating system working","Smoke alarms on each floor including basement (10-year sealed battery); CO alarms near bedrooms if there is a gas or oil appliance; ABC extinguisher no larger than 10 lbs within 10 feet of the kitchen","Work done without permits and open permits must be resolved","Also: Taxes, grass cutting charges and liens paid first: All charges (taxes, grass, liens, etc.) must be paid before the CO application is accepted, even if they would be paid at settlement. Call 856-933-1313.","Also: Open permits and vacant property fees: Any vacant property fees and open permits must be closed out before any certificate is issued."]$j$::jsonb, $j$[{"label":"Resale CO inspection (cash or check only)","amount":"$100"},{"label":"Second inspection","amount":"No charge"},{"label":"Third inspection (re-inspection)","amount":"$75"},{"label":"Fourth or later re-inspection, each","amount":"$100"}]$j$::jsonb, $t$https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF$t$, $t$https://www.bellmawr.com/172/Certificates-of-Occupancy$t$, $j$[{"url":"https://www.bellmawr.com/172/Certificates-of-Occupancy","label":"Official source (bellmawr.com)"},{"url":"https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF","label":"Official source (bellmawr.com)"}]$j$::jsonb, $t$Must be obtained prior to settlement.$t$, $t$1a3e26d9ae54be0dcb304d2e8499faec50b7a852d450bca4c1ee34bfdbbecb02$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0404.json$t$, true),
  ($t$0404$t$, $t$Bellmawr Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bellmawr Fire Department, Bureau of Fire Prevention (Fire Marshal's Office) (town fire bureau)","Contact: 856-933-1313 ext. 1239 · rfowler@bellmawr.com","Apply: Schedule at least 10 days ahead for the lowest fee","How to apply: Fill out page 1 of the Bureau of Fire Prevention Certification of Smoke Detector and Carbon Monoxide Alarm Compliance application and return it with a check or money order payable to Borough of Bellmawr (no refunds). Pay separately from the CO fee. Office: 21 E. Browning Road; Fire Marshal's Office 856-933-1313 ext. 1239.","Fire official in the NJ state directory (town), updated 5/26/2026: Robert T Fowler · (856) 933-1313 · rfowler@bellmawr.com","Smoke alarms must match the rules in effect when the house was built (hardwired and interconnected in newer homes); hardwired alarms cannot be replaced with battery units","Smoke alarms no more than 10 years from date of manufacture; 10-year sealed battery where battery alarms are used","Smoke alarm within 10 feet of every bedroom door; basement alarm within 10 feet of the stair opening","Alarms mounted with proper hardware; nails, tacks, tape or Velcro not accepted; 3 feet from fan blades and HVAC vents","CO alarm outside sleeping areas, no more than 10 feet from any bedroom","Monitored alarm systems in homes built 1977 or later must be kept working","Borough CO checklist asks for an ABC extinguisher no larger than 10 lbs within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, appointment scheduled at least 10 days ahead","amount":"$70.00"},{"label":"Smoke/CO certificate, scheduled less than 10 but more than 4 days ahead","amount":"$100.00"},{"label":"Smoke/CO certificate, scheduled less than 4 days ahead","amount":"$140.00"},{"label":"Reinspection","amount":"$50.00"},{"label":"No-show for appointment","amount":"$50.00"}]$j$::jsonb, $t$https://www.bellmawr.com/DocumentCenter/View/1564/Smoke-DetectorCarbon-Monoxcide-Alarm-Application-PDF$t$, $t$https://bellmawrfire.com/homepage/fire-marshals-office/$t$, $j$[{"url":"https://www.bellmawr.com/DocumentCenter/View/1564/Smoke-DetectorCarbon-Monoxcide-Alarm-Application-PDF","label":"Official source (bellmawr.com)"},{"url":"https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF","label":"Official source (bellmawr.com)"},{"url":"https://bellmawrfire.com/homepage/fire-marshals-office/","label":"Official source (bellmawrfire.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification of Smoke Detector & Carbon Monoxide Alarm Compliance$t$, $t$bca75da283e174ca23cafacb8994b2648e2dcc7cfcf8c5a652463cedb4c4ba8c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0404.json$t$, true),
  ($t$0405$t$, $t$Berlin Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Berlin Construction Department","Contact: 856-767-7777 ext. 316 · construction@berlinnj.org","How to apply: Fill out the Inspection Application for Certificate of Continued Occupancy (check 'House Sale') and submit it to the Construction Department, 59 S. White Horse Pike, Berlin. The Tax Collector must certify that taxes are current and there are no liens. Inspection requests can be emailed to construction@berlinnj.org.","All utilities on for the inspection; lockbox code if vacant","Trash and debris cleared inside and out","Walkways level and free of trip hazards","4 inch contrasting house number visible from the street","Graspable handrail on steps with more than four risers; guardrails on open stairs","Windows and doors operable, no cracked or broken glass","No pest or rodent infestation","Egress window or door in every bedroom; no bedrooms in basements","Bathroom window or exhaust fan","Dryer vent hard piped to the outside","Water heater discharge pipe ending 2 to 6 inches above the floor","Smoke detectors working on every level, under 10 years old, 10-year sealed battery if battery powered, hardwired units interconnected and not swapped for battery units","CO detector within 10 feet of each bedroom","Pools, fences, garages and decks safe; pool gates self-closing and self-latching","Wood-burning fireplace or stove needs a certificate showing it is in good working order","Also: Tax Collector certification: The CCO application includes a Tax Collector sign-off that taxes are current and there are no liens.","Also: Open permits closed: All open permits must be closed with final passing inspections before a CCO is issued."]$j$::jsonb, $j$[{"label":"Initial CCO inspection","amount":"$100"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf$t$, $t$https://www.berlinnj.org/construction/$t$, $j$[{"url":"https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf","label":"Official source (berlinnj.org)"},{"url":"https://berlinnj.org/berlinnj/AGENDA%20%202020-07-09.pdf","label":"Official source (berlinnj.org)"}]$j$::jsonb, $t$INSPECTION APPLICATION FOR CERTIFICATE OF CONTINUED OCCUPANCY$t$, $t$2a80a1aeff6fed330f6891ee245f252998b3f045d97bf2db83724df6f8d37a14$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0405.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0405.json$t$, true),
  ($t$0405$t$, $t$Berlin Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Berlin Borough Bureau of Fire Prevention (town fire bureau)","Contact: 856-767-7777 ext. 308","Apply: Allow two to three weeks before settlement; over 10 business days for the lowest fee","How to apply: Fill out the Application for Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance and mail it with a check payable to 'Borough of Berlin' to Berlin Bureau of Fire Prevention, PO Box 226, Berlin, NJ 08009. The property must be ready for inspection.","Fire official in the NJ state directory, updated 5/19/2026: William Behnke · (856) 767-7777 · fm211@berlinnj.org","Battery smoke detectors must be 10-year sealed battery units (Bureau notice, 'Effective Immediately')","Hardwired smoke alarms from original construction may not be replaced with battery alarms","If the home has a monitored alarm system, notify the alarm company before the test and have the codes available at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSDCMAC, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"CSDCMAC, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"CSDCMAC, request received fewer than 4 business days before change of occupant","amount":"$161.00"},{"label":"Additional fee if more than two visits are needed","amount":"$45.00"}]$j$::jsonb, $t$https://www.berlinnj.org/CSDCMAC%20app.pdf$t$, $t$https://www.berlinnj.org/bureau-of-fire-prevention/$t$, $j$[{"url":"https://www.berlinnj.org/CSDCMAC%20app.pdf","label":"Official source (berlinnj.org)"},{"url":"https://www.berlinnj.org/wp-content/uploads/2026/07/Battery-Smoke-Detector.pdf","label":"Official source (berlinnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application fee for a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC), as required by N.J.A.C. 5:70-2.3, shall be based upon the amount of time remaining before the change of occupant is expected, as follows:$t$, $t$2a9abdd5153b470852b8d6a0b5dc8a2f66dde118117a192ff08b6b892e8ceb8d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0405.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0405.json$t$, true),
  ($t$0406$t$, $t$Berlin Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Berlin Township requires a resale certificate. Call the office before closing."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://berlintwp.com/$t$, $j$[]$j$::jsonb, null, $t$700ab5813e97a10184bbad0cc09a89f8008656d97e60b3fde00a391c0650fcf3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":2,"q_ok":2,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0406.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0406.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0406$t$, $t$Berlin Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Berlin Township Fire District No. 1 (Board of Fire Commissioners) (fire district)","How to apply: No application or fee schedule was found online. The Township website links 'Berlin Township Fire Department' to www.westberlinfire.com, which now redirects to a Facebook page (West Berlin Fire Rescue). Contact the fire district directly.","Fire official in the NJ state directory (fire district), updated 8/5/2026: Joseph V Cornforth · (856) 767-1839 · firemarshal222@gmail.com","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/divisions/dlgs/programs/lpcl_docs/cd_camden.docx","label":"Official source (nj.gov)"}]$j$::jsonb, $t$D Berlin Township$t$, $t$e0f71a9c21a7730da5774a4e3d686152074d4a2806d445b7dbbde9fe640ffb09$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":2,"q_ok":2,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0406.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0406.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0407$t$, $t$Brooklawn Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy / Housing Inspection (Residential Dwelling Resale)$t$, $j$["Issued by: Borough of Brooklawn Construction/Zoning/Code Enforcement","Contact: 856-456-0750 ext. 105 · mperry@brooklawn-nj.com","Apply: Application and fee must be received before any inspection is scheduled; no set number of days published","How to apply: Fill out the Application for Continued Certificate of Occupancy/Housing Inspection (check 'Residential Dwelling RESALE') and bring or mail it with the fee (cash or check payable to Borough of Brooklawn, mailed 'Attn: Construction') to 301 Christiana St., Brooklawn. Then call the office to schedule. Inspections are by appointment only, Tuesday and Thursday 10:00 am to 12:00 pm. The report can be ma","Also: Water final reading: Water final reading request is $25.00, payable by check to Borough of Brooklawn, cash or money order. The form adds: 'If settlement date is within 3 days from the date of application, the fee is $100.00'; it is unclear whether that $100.00 "]$j$::jsonb, $j$[{"label":"Residential dwelling resale CO","amount":"$100.00"},{"label":"CO re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf$t$, $t$https://brooklawn-nj.com/departments/construction/$t$, $j$[{"url":"https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf","label":"Official source (brooklawn-nj.com)"},{"url":"https://brooklawn-nj.com/frequently-used-forms","label":"Official source (brooklawn-nj.com)"}]$j$::jsonb, $t$CO Inspections for both Rental Properties / Residential Sales or Commercial Properties are completed on Tuesday & Thursday between 10:00 am -12:00 pm by appointment only Application and fee must be received prior to scheduling any Inspection$t$, $t$c43db79ef563d8df39a4f3dd072aa017d1103cdfb66a08a22e52c2c8e307224d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":3,"q_ok":2,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0407.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0407.json$t$, true),
  ($t$0407$t$, $t$Brooklawn Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Brooklawn Borough fire official (Fire Department is the local enforcing agency) (town fire bureau)","Contact: 856-456-0750","How to apply: No smoke/CO certificate form or fee schedule was found on the Borough website. Contact the Borough office at 856-456-0750.","Fire official in the NJ state directory, updated 3/19/2026: Timothy O'Donnell · (856) 456-0750 · Timothy.O’Donnell@salemcountynj.g","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://brooklawn-nj.com/departments/public-safety/fire/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$F Brooklawn Borough$t$, $t$498f2b6d6bec9ae8df540bff78c73e3672ea2de0ee38b26a852c776cbdd4b1c0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":3,"q_ok":2,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0407.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0407.json$t$, true),
  ($t$0408$t$, $t$Camden City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Camden Resale Occupancy Certificate (C.R.O.C.); formerly Certificate of Continued Occupancy (C.C.O.)$t$, $j$["Issued by: City of Camden Construction & Building Bureau (Department of Code Enforcement)","Contact: 856-757-7032","Apply: Zoning approval must be obtained first; no set number of days published","How to apply: First apply for a zoning permit (Zoning, City Hall Room 224, 856-757-7214). After zoning approval, submit the application to the Building Bureau, City Hall Room 403, 520 Market Street (856-757-7032). The seller is responsible for applying; the buyer may apply as the seller's agent with written permission, and the certificate is issued to the buyer. Building Bureau visits are by appointment only (c","Valid for: Application is good for 6 months","Zoning permit and zoning approval before the application is accepted","Building, electrical, plumbing and fire inspections by the Building Bureau","All open building permits must be closed before the inspection","General inspection of the visible parts of the building for Uniform Construction Code violations","Also: Zoning approval first: A zoning permit and approval are required before the Building Bureau accepts the CCO/C.R.O.C. application. Zoning: City Hall Room 224, 856-757-7214.","Also: Open permits closed: All existing open building permits must be closed out before the CCO inspection; no certificate is issued while permits are open."]$j$::jsonb, $j$[{"label":"C.R.O.C. application","amount":"$200.00"},{"label":"CCO application fee (form)","amount":"$200.00"},{"label":"Name change on the CCO","amount":"$37.00"},{"label":"Penalty if the buyer closes without the certificate (up to)","amount":"$2,000.00"}]$j$::jsonb, $t$https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf$t$, $t$https://www.camdennj.gov/construction-building-bureau/$t$, $j$[{"url":"https://www.camdennj.gov/faq-items/what-is-a-c-r-o-c/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/building-bureau-faqs/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/construction-building-bureau/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf","label":"Official source (camdennj.gov)"}]$j$::jsonb, $t$The City of Camden requires that a Camden Resale Occupancy Certificate shall be applied for and issued prior to the sale or conveyance of any property within the city.$t$, $t$de9caf113a47d0a0bc65d42faf47d8ee1256e752f1c20fd36af9bd853cf38ac9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0408.json$t$, true),
  ($t$0408$t$, $t$Camden City$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Camden Fire Department, Office of the Fire Marshal (town fire bureau)","Contact: 856-757-7531 · RaBarker@camdennj.gov","Apply: Submit the request 3 to 4 weeks before settlement; 8 or more calendar days ahead for the lowest fee","How to apply: Fill out the Residential Inspection Request Form and email it to Raymond Barker (RaBarker@camdennj.gov) or call 856-757-7531. Pay by check or money order payable to 'Uniform Fire Safety Act' (UFSA) before the inspection, or mail it in advance to Camden Fire Department, Office of the Fire Marshal, 4 N. 3rd Street, Camden, NJ 08102. Cash is not accepted. Inspections are between 9:00 am and 3:00 pm.","Fire official in the NJ state directory, updated 5/22/2026: Joseph Tull, Sr. · (856) 757-7531 · JoTull@camdennj.gov","10-year sealed battery smoke alarm on every level, or hardwired where required; hardwired alarms cannot be replaced with battery units","Smoke alarm on the ceiling in every bedroom","Basement alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarm within 10 feet of all bedroom doors","Hardwired smoke alarms and CO alarms must be less than 10 years old and working","CO alarm in the hallway within 10 feet of all bedrooms; not in switched outlets or outlets at floor molding","Fire extinguisher within 10 feet of the kitchen in the path of exit, mounted on a bracket, minimum rating 2A-10B:C, under 10 pounds","House numbers at least 4 inches, contrasting, fixed to the house and visible from the street (numbers on a light post or mailbox not accepted)","Monitored low-voltage fire alarm systems must be tested by an alarm contractor, with the certification given to the inspector","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$64.00"},{"label":"Request received with less notice (published as 'seven (7) calendar days or more')","amount":"$115.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$162.00"},{"label":"Re-inspection","amount":"$35.00"},{"label":"Senior discount (sellers 62 and over, first inspection, proof of age required)","amount":"$30.00"}]$j$::jsonb, $t$https://www.camdennj.gov/wp-content/uploads/2025/07/New-Residitial-request-from-2025V2.pdf$t$, $t$https://www.camdennj.gov/fire-marshal/$t$, $j$[{"url":"https://www.camdennj.gov/wp-content/uploads/2024/08/Residential-Resale-Requirements.pdf","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2025/07/New-Residitial-request-from-2025V2.pdf","label":"Official source (camdennj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Residential Resale Requirements for One & Two Family Dwellings Certificate of Smoke Detector, Fire Extinguisher & Carbon Monoxide Alarm Compliance$t$, $t$ab99281d08c2a5c594ad4a7fba6f78c447056c2ed0f7378c1fdd850f6293df47$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0408.json$t$, true),
  ($t$0409$t$, $t$Cherry Hill Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Residential Resale Inspection$t$, $j$["Issued by: Community Development, Property Maintenance Department","Contact: 856-834-3364","Apply: No minimum lead time published. Inspections occur within 7 business days of receipt of application and fee.","How to apply: Apply online (office approves first, then SDL Portal emails a payment request), or download the paper application and mail it or drop it off with a check or money order payable to Cherry Hill Township at 820 Mercer Street, Room 202, Cherry Hill, NJ 08002. Fee must be paid before the inspection. No refunds once paid.","Exterior-only inspection; no one needs to be home","Sidewalks, walkways, stairs and driveways in good repair, including sidewalk up to the curb line","Fences, detached garages and other accessory structures structurally sound","Dead or dying trees and hazardous limbs removed or trimmed","Weeds and grass under 10 inches","Property clean and sanitary","Grading and drainage: no ponding, no runoff onto neighbors","Sump pump and roof drain discharge not affecting neighbors or the roadway","Exhaust vents","No ground surface hazards such as holes or broken walks","No unregistered, uninsured or disassembled vehicles stored on the property","Also: Two separate inspections: The Property Maintenance CCO is in addition to the Cherry Hill Fire Department smoke alarm inspection."]$j$::jsonb, $j$[{"label":"CCO exterior inspection","amount":"$100"}]$j$::jsonb, $t$https://chnj.gov/1107/Online-CCO-Application$t$, $t$https://chnj.gov/893/Residential-Resale-Inspections$t$, $j$[{"url":"https://chnj.gov/893/Residential-Resale-Inspections","label":"Official source (chnj.gov)"},{"url":"https://chnj.gov/DocumentCenter/View/2486","label":"Official source (chnj.gov)"}]$j$::jsonb, $t$Cherry Hill homeowners are required to obtain a Certificate of Continued Occupancy prior to the resale of any single-family residential property in Cherry Hill.$t$, $t$1602e02149d2d43dde937c8038d8a33fa5fd2128d781b117109f311bb261ad0a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0409.json$t$, true),
  ($t$0409$t$, $t$Cherry Hill Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cherry Hill Fire Department (Cherry Hill Fire District #13) (fire district)","Contact: 856-429-7441 · sdi@chfd.org","Apply: Submit the request 3 to 4 weeks before the settlement date","How to apply: Submit the online Residential Inspection Request Form (not for re-inspections or rentals). Pay at the time of inspection by credit card, check or money order payable to CHFD; no cash. Certificate is issued at the inspection if the home passes and payment is received. Temporary certificates are not issued. Certificates are valid for 90 days.","Fire official in the NJ state directory (fire district), updated 1/23/2026: Joseph V Cornforth · (856) 795-1340 · jcornforth@chfd.org","10-year sealed battery smoke alarm on every level, in every bedroom (on the ceiling), and within 10 feet of all bedroom doors; hardwired alarms cannot be swapped for battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","Smoke and CO alarms must be less than 10 years old and working","CO alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently on the house and visible from the street (mailbox or light post numbers not accepted)","Homes with a secondary power source (solar, generator, battery storage) need a permanent, non-handwritten label at the main electrical panel and the electric meter, such as 'Caution: Multiple Sources of Power'","Homes with a low-voltage fire alarm system must have it tested by an alarm contractor before the inspection and show the certification to the inspector","The township page says fire extinguishers are no longer required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 8 or more calendar days before settlement","amount":"$100.00"},{"label":"Request received 7 calendar days before settlement","amount":"$115.00"},{"label":"Request received 3 calendar days or less before settlement","amount":"$162.00"},{"label":"Re-inspection","amount":"$35.00"},{"label":"Senior discount, sellers 62 and over (off initial fee, proof of age required)","amount":"$30.00"}]$j$::jsonb, $t$https://chnj.gov/forms.aspx?FID=107$t$, $t$https://chnj.gov/232/Smoke-Carbon-Monoxide-Alarm-Compliance$t$, $j$[{"url":"https://chnj.gov/232/Smoke-Carbon-Monoxide-Alarm-Compliance","label":"Official source (chnj.gov)"},{"url":"https://chnj.gov/DocumentCenter/View/400/Residential-Resale-Inspection-Requirements","label":"Official source (chnj.gov)"},{"url":"https://chnj.gov/ArchiveCenter/ViewFile/Item/2779","label":"Official source (chnj.gov)"}]$j$::jsonb, $t$When selling a one or two family home in Cherry Hill, you must obtain a Certificate of Smoke Alarm and Carbon Monoxide Detector Compliance CSACMAPFEC 5:70-2.3 (a) prior to the settlement.$t$, $t$27ed8d287838bdb0079995306840528284d5350d5229b588558ce0f17904de62$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0409.json$t$, true),
  ($t$0410$t$, $t$Chesilhurst Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Chesilhurst Borough requires a resale certificate. Call the office before closing.","Contact: 856-767-4153"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://chesilhurstboro.org/departments/construction/$t$, $j$[]$j$::jsonb, null, $t$a122a3034481466fdd982d44a425646c578552852ad3fe0a6f51971c4ad43773$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0410.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0410.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0410$t$, $t$Chesilhurst Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Winslow Township Fire Department, Fire Prevention Division (Winslow Township Fire District) (fire district)","Contact: 609-561-4225 · firedistrict@winslowtwpfd.org","Apply: Apply 3 to 4 weeks before the closing or move-in date","How to apply: Apply online through the Winslow Township Fire Department resale application, then pay through the Edmunds WIPP payment link; or download the packet and fax it to 609-561-5823; or apply in person at 9 Cedar Brook Road, Sicklerville (9 am to 5 pm weekdays). Pay by check (payable to Winslow Township Fire District), credit card, debit card or money order. Inspections are Tuesdays and Thursdays in a m","Fire official in the NJ state directory (fire district), updated 12/9/2025: Joseph G Hahn · (609) 561-4225 · josephh@winslowtwpfd.org","All battery (DC) smoke alarms must be 10-year sealed battery alarms","Smoke alarms must be less than 10 years old; the realtor, owner, seller or buyer must take each alarm down and check the date","Smoke alarm type and number follow the year the house was built (for example 1991 to present: hardwired alarms with battery backup on each level and in each bedroom, interconnected); hardwired alarms cannot be replaced with a single battery alarm","CO alarm within 10 feet of all sleeping areas if the home has a fuel-burning appliance, fireplace or attached garage","Homes with a secondary power source (solar, generator, battery storage) need a permanent, non-handwritten label at the main electrical panel and electric meter, such as 'Caution: Multiple Sources of Power'","Homes with a low-voltage fire alarm system must have it certified by an alarm contractor before the inspection","Electric power must be on; an adult (18+) must be present for the whole inspection; inspectors do not use lockboxes","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"8 or more days advance notice (instructions sheet)","amount":"$65.00"},{"label":"4 to 7 days notice","amount":"$100.00"},{"label":"3 days or less notice","amount":"$150.00"},{"label":"Senior discount, 62 or older (proof of age)","amount":"$30.00"},{"label":"Re-inspection, per visit","amount":"$35.00"},{"label":"Failure to keep appointment (no-show)","amount":"$35.00"}]$j$::jsonb, $t$https://winslowtwpfd.org/online-resale-application$t$, $t$https://winslowtwpfd.org/fire-marshal-office$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://winslowtwpfd.org/fire-marshal-office","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/Smoke_Application_2025.pdf","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/CSDCMACPFE_Instructions_4.15.2025.pdf","label":"Official source (winslowtwpfd.org)"}]$j$::jsonb, $t$Winslow Township is the LEA for Chesilhurst Borough.$t$, $t$75d43c1f0d292c534f422d6b951e8877cb7467d0c85bc961ddfb37d48034524d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0410.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0410.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0411$t$, $t$Clementon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) for a Residential Resale$t$, $j$["Issued by: Code Enforcement Office","Contact: 856-783-0284 ext. 127 · CodeEnforcePnZ@clementon-nj.com","How to apply: Download the CCO Application for a Residential Resale, fill it out (seller, buyer, closing date, contacts) and submit it to Code Enforcement, Borough of Clementon, 101 Gibbsboro Road, Clementon, NJ 08021, with the fee (the form records a money order or check number).","House number at least 4 inches high, visible from the street","Steps and walkways without trip hazards; cracked sidewalk blocks with a height change replaced","Guardrails where a porch, landing or stairs is over 30 inches above grade; handrail on steps with 4 or more risers","Yard free of high grass, weeds, dead trees, debris and hazards","Gutters and downspouts attached and clear, with splash blocks or diverters","Basement/crawl space openings and exterior doors secure and weatherproof; sump pump discharge outside, not into the sanitary sewer","No signs of pests (otherwise a licensed pest control certification is needed)","Bathroom window or exhaust fan; GFI protection on existing bathroom, kitchen counter, garage and exterior outlets","Cover plates on all switches and outlets; electrical panel secure, labeled, no open breaker slots; A/C disconnect at the outdoor unit","Windows intact; bedroom windows open and close for emergency escape","Water heater relief valve with discharge pipe ending 2 to 6 inches above the floor; tight flue connections","No plumbing leaks; fixtures and toilets secure","Heating system working","Work done without permits will be cited; open permits must be closed out","Also: Open permits must be closed: Any permits without final inspections or a Certificate of Approval must be closed out; contact the borough beforehand to ask if the address has anything open. Work done without permits will be cited."]$j$::jsonb, $j$[{"label":"1 and 2 family house or condo ($60 / $120; form does not spell out which applies to which, likely $60 for one unit and $120 for two)","amount":"$60/$120"},{"label":"3 and 4 family house, per unit","amount":"$60 per unit"},{"label":"Reinspection","amount":"$30"}]$j$::jsonb, $t$https://clementon-nj.com/wp-content/uploads/2025/03/certificate_of_occupancy.pdf$t$, $t$https://clementon-nj.com/code-enforcement/$t$, $j$[{"url":"https://clementon-nj.com/code-enforcement/","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/wp-content/uploads/2025/03/certificate_of_occupancy.pdf","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/wp-content/uploads/2021/04/RESALE-CO-INSPECTION-FORM.pdf","label":"Official source (clementon-nj.com)"}]$j$::jsonb, $t$Certificate of Occupancy Certificate required for sales and rentals$t$, $t$817f58d6e905e35a7798d23d32e561d02927e8c9037dfb3caecfab26e0629f4d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":5,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0411.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0411.json$t$, true),
  ($t$0411$t$, $t$Clementon Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Clementon Bureau of Fire Safety (town fire bureau)","Contact: 856-783-0284 ext. 123 · jzuggi@clementon-nj.com","Apply: More than 10 business days before closing for the lowest fee","How to apply: Download the application, fill it out (closing date, bedrooms, year built, lockbox code) and submit it with the fee to the Bureau of Fire Safety, 101 Gibbsboro Road, Clementon. Applications sent by email or fax are not processed until payment is received. Certificates are valid for 6 months or until the date of closing/change in occupancy.","Fire official in the NJ state directory (town), updated 8/5/2026: John J Zuggi · (856) 783-0284 · jzuggi@clementon-nj.com","Homes built before 1977: 10-year sealed battery smoke alarms on each level and within 10 feet of bedrooms","Homes built after 1977: hardwired, interconnected smoke alarms on each level and within 10 feet of bedrooms; 1990s and newer also need battery backup and an alarm in each bedroom","All single-station smoke alarms must be 10-year sealed battery type (effective 01/01/2019)","CO alarm within 10 feet of sleeping areas","2A:10B:C fire extinguisher, not more than 10 pounds, mounted with the maker's hanger or bracket, visible and within 10 feet of the kitchen, with an inspection tag or a store receipt from the last 12 months","House number at least 3 inches, contrasting color, on the street side","A cottage or garage apartment being sold needs its own application and fee","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change of occupants","amount":"$ 60.00"},{"label":"Request received 4 to 10 business days before","amount":"$ 100.00"},{"label":"Request received 2 to 4 business days before","amount":"$ 161.00"},{"label":"Same day of settlement or one day","amount":"$ 200.00"},{"label":"Re-inspection after a failed initial inspection","amount":"$ 35.00"}]$j$::jsonb, $t$https://clementon-nj.com/wp-content/uploads/2023/09/Fire-Safety.pdf$t$, $t$https://clementon-nj.com/fire-safety/$t$, $j$[{"url":"https://clementon-nj.com/wp-content/uploads/2023/09/Fire-Safety.pdf","label":"Official source (clementon-nj.com)"},{"url":"https://clementon-nj.com/fire-safety/","label":"Official source (clementon-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$No owner shall sell, lease or otherwise permit occupancy for residential purpose of any structure or intended for use as a single-family or two-family structure without obtaining a certificate of smoke alarm, carbon monoxide alarm and portable fire extinguisher compliance (CSACMAPFEC).$t$, $t$0c9cf6a0c692053004940504b6a8de9dd8de64f6a8955e5d47eae2d125fea659$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":5,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0411.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0411.json$t$, true),
  ($t$0412$t$, $t$Collingswood Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (CO) Resale / Exterior Resale Certification (Exterior Housing Code Inspection, Borough Ordinance 227-3)$t$, $j$["Issued by: Collingswood Fire Department, Office of Fire Prevention & Inspection Bureau","Contact: 856-854-7447 x101 · fireprevention@collingswood.com","How to apply: Use the combined 'Residential Inspection for Sale of Property Application' (covers both the exterior resale certificate and the fire CSACMAPFEC). Print, complete and deliver it with a check or money order payable to 'Borough of Collingswood' to the Fire Prevention & Inspection Bureau, 434 Haddon Avenue, Collingswood NJ 08108. One check may cover both inspections. Call 856-854-7447 to schedule (ins","Valid for: 6 months from the date of inspection, or one change of ownership","Exterior only: sidewalks, walkways, curbing, driveways and aprons, exterior stairs and handrails, house numbers","Sidewalks and walkways free of trip hazards (1/2 inch or more height difference between blocks, or cracks 1/4 inch or wider); bad blocks replaced, not patched; Public Works permit needed","Curbs free of disintegration and cracks over 1/2 inch","Driveways in good condition, at least 9 by 18 feet; dirt, grass, gravel, stone or shell surfaces not allowed","Exterior stairs with more than 4 risers or over 30 inches high need handrails and guards","House numbers at least 3 1/2 inches high, readable from the street","Repairs must be finished within 30 days of notice; a shade tree permit is needed if trees are in the curb strip","No open construction permits and no outstanding zoning violations (signed affidavits from the Construction Office and Zoning Office)","Also: Construction Permit Affidavit: Construction Office must certify there are no open permits.","Also: Zoning Official Affidavit: Zoning Office must certify there are no outstanding zoning violations.","Also: Sidewalk/curb repair permit: Owner must get a Public Works permit before sidewalk or curb repairs; Shade Tree Commission permit if trees are in the curb strip. Public Works: 856-854-0533."]$j$::jsonb, $j$[{"label":"Exterior resale inspection","amount":"$ 50.00"},{"label":"Re-inspection (applies to all re-inspections)","amount":"$50.00"},{"label":"Returned check processing fee","amount":"$20.00"}]$j$::jsonb, $t$https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130$t$, $t$https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php$t$, $j$[{"url":"https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php","label":"Official source (collingswood.com)"},{"url":"https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130","label":"Official source (collingswood.com)"}]$j$::jsonb, $t$There are several types of Certificates of Occupancy (COs). This type is required at the time of resale of any property in the Borough of Collingswood. The criteria for this CO are contained in Chapter 227-3 of the Collingswood Code$t$, $t$fe0168aff404ceb6594314fb0c4df88729389d40155833b34e6ad0805005fef9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0412.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0412.json$t$, true),
  ($t$0412$t$, $t$Collingswood Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Collingswood Fire Department, Office of Fire Prevention & Inspection Bureau (town fire bureau)","Contact: 856-854-7447 · fireprevention@collingswood.com","Apply: Apply more than 10 days before the inspection appointment for the lower fee","How to apply: Same combined application as the exterior resale certificate. Submit with a check or money order payable to 'Borough of Collingswood' to 434 Haddon Avenue; fees are due at application. Call 856-854-7447 to schedule. Certificates are valid for one change of ownership or 6 months, whichever comes first.","Fire official in the NJ state directory, updated 1/9/2026: Geoffrey T Joyce · (856) 854-7447 · gjoyce@collingswood.com","Working 10-year sealed battery smoke alarm in every bedroom and on every level (hardwired 110V alarms are exempt from the 10-year battery rule but must be tested to NFPA 72 with a test report at inspection)","Smoke alarms on the ceiling at least 4 inches from the wall, or on the wall 4 to 12 inches below the ceiling","CO alarm within 10 feet of each sleeping area","Homes with a secondary power source (generator, solar, battery storage) need a non-handwritten label within 18 inches of the main electrical panel and electric meter, such as 'CAUTION: MULTIPLE SOURCES OF POWER'","Fire extinguisher no longer required (removed February 2025 under P.L.2025, c.19)","A representative must be present to let the inspector in","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Interior CSACMAPFEC, application more than 10 days before inspection appointment","amount":"$75.00"},{"label":"Interior CSACMAPFEC, application less than 10 days before inspection appointment","amount":"$150.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130$t$, $t$https://www.collingswood.com/government/departments/fire.php$t$, $j$[{"url":"https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130","label":"Official source (collingswood.com)"},{"url":"https://www.collingswood.com/government/departments/fire.php","label":"Official source (collingswood.com)"}]$j$::jsonb, $t$Application for CSACMAPFEC & Exterior Resale Certification$t$, $t$ea22b1494ec54d54c71fb4b661bd84f980bd2581f6e5fe3e3d711865d6418056$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0412.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0412.json$t$, true),
  ($t$0413$t$, $t$Gibbsboro Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continuing Certificate of Occupancy (CCO), Borough Code Chapter 132$t$, $j$["Issued by: Code Enforcement Office (Code Enforcement Officer / Fire Official)","Contact: 856-783-6655 ext. 151 · codeenforcement@gibbsborotownhall.com","Apply: Inspections require 15 days notice","How to apply: Download the CCO application, fill in seller, buyer and settlement date, sign, and submit with a check to the borough (49 Kirkwood Rd, Gibbsboro). Call or email to schedule; inspection times vary.","Yard","Sidewalks, curbing and driveway","Roof, rain spouts, chimneys and exterior","Windows","Stairs and handrails","Plumbing, heating and electrical","Attic, basement and foundation","Fireplaces","Handicap items","Outstanding building permits and zoning are checked on the application","Also: Outstanding building permits and zoning: The CCO application has fields for outstanding building permits and zoning, which are reviewed as part of the CCO."]$j$::jsonb, $j$[{"label":"Initial inspection (within 10 business days)","amount":"$125.00"},{"label":"Initial inspection (within 5 business days)","amount":"$150.00"},{"label":"Initial inspection (within 2 business days)","amount":"$175.00"},{"label":"Second and later reinspections (first reinspection free)","amount":"$ 50.00"}]$j$::jsonb, $t$https://gibbsborotownhall.com/wp-content/uploads/2023/06/CCO_APPLICATION_Residents_06212023.pdf$t$, $t$https://gibbsborotownhall.com/code-enforcement/$t$, $j$[{"url":"https://gibbsborotownhall.com/code-enforcement/","label":"Official source (gibbsborotownhall.com)"},{"url":"https://gibbsborotownhall.com/wp-content/uploads/2023/06/CCO_APPLICATION_Residents_06212023.pdf","label":"Official source (gibbsborotownhall.com)"}]$j$::jsonb, $t$A CCO is required prior to the sale of all commercial and residential properties and whenever there is a change in tenant.$t$, $t$e57aeacffc7b37aa3c3615b844d1a55e311368fea852434895b42d96dc39485d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0413.json$t$, true),
  ($t$0413$t$, $t$Gibbsboro Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Gibbsboro Bureau of Fire Safety (Borough Fire Official) (town fire bureau)","Contact: 856-783-6655 ext. 151 · fireofficial@gibbsborotownhall.com","Apply: 10 days advance notice needed to schedule; less than 10 days costs more","How to apply: Mail the application with a check or money order payable to 'Gibbsboro Bureau of Fire Safety' to 49 Kirkwood Rd, Gibbsboro, NJ 08026, or drop it in the lock box in front of the building. Payment must accompany the application; no cash, no payment on site.","Fire official in the NJ state directory (town), updated 7/22/2026: Craig C Fallstick Sr · (856) 783-6655 · fireofficial@gibbsborotownhall.com","Smoke alarms on every level including the basement and within 10 feet of bedrooms; all smoke alarms, including hardwired, must be under 10 years old","10-year sealed battery smoke alarms required; non-sealed battery alarms not accepted; hardwired alarms must be replaced with hardwired","CO alarm on each level with a sleeping area, near the bedrooms; the form says CO alarms must be under 5 years old","Fire extinguisher (form dated 2023): at least 5 lb 2A:10BC and no larger than 10 lb 4A:60BC, charged, mounted in plain view within 10 feet of the kitchen, not behind doors or in a cabinet","Fire alarm systems must be put on test through the alarm company; owner must know codes to silence and reset","Someone over 18 must be present","If the change of occupancy does not occur within 6 months, a new application is required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"10 or more days notice","amount":"$45.00"},{"label":"4 to 10 days notice","amount":"$90.00"},{"label":"4 days or less notice","amount":"$161.00"},{"label":"Failure / re-inspection","amount":"$ 35.00"},{"label":"Missed appointment or entry denied","amount":"$ 15.00"}]$j$::jsonb, $t$https://gibbsborotownhall.com/wp-content/uploads/2023/06/Smoke_Residents_06212023.pdf$t$, $t$https://gibbsborotownhall.com/fire-official/$t$, $j$[{"url":"https://gibbsborotownhall.com/wp-content/uploads/2023/06/Smoke_Residents_06212023.pdf","label":"Official source (gibbsborotownhall.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Payment should be made to “Gibbsboro Bureau of Fire Safety” and must accompany this application.$t$, $t$a998006edc77c6d7ad6b307db4cbb6c0242c10dcf6f247100b17936ef710c096$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0413.json$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Gloucester City requires a resale certificate. Call the office before closing."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[]$j$::jsonb, null, $t$e98f16d9023fc44130cf0657d71ffa92a13c1875f3e3580ae03a75b86eb0f77b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":3,"q_ok":3,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0414$t$, $t$Gloucester City$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Gloucester City Fire Department (Fire Official Patrick R. Hagan); DCA directory lists 'Gloucester City Housing' as the smoke detector compliance contact (town fire bureau)","Contact: 856-456-7689 · pat.hagan@gloucestercityfd.org","How to apply: No application form or instructions could be read (city website behind a bot check). The DCA Fire Department/LEA Directory lists the smoke detector compliance contact as Gloucester City Housing, 512 Monmouth St, Gloucester City NJ 08030, phone (856) 456-7689. Fire Official: Patrick R. Hagan, (856) 456-2652, pat.hagan@gloucestercityfd.org.","Fire official in the NJ state directory, updated 5/22/2026: Patrick R Hagan · (856) 456-2652 · pat.hagan@gloucestercityfd.org","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, null, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$F Gloucester City$t$, $t$900a23fd268e5254e3a1258b497d36b82dc138d6ad5c31e632bf6ffa1f5ac046$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online","no published fees found"],"verification":{"fees":0,"fee_ok":0,"fee_bad":0,"fee_unchecked":0,"quotes":3,"q_ok":3,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0414.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0414.json. Red flag: town certificate not confirmed online; no published fees found$t$, true),
  ($t$0415$t$, $t$Gloucester Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Gloucester Township requires a resale certificate. Call the office before closing.","Contact: 856-374-3500"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://glotwp.com/department/community-development-planning/$t$, $j$[]$j$::jsonb, null, $t$80cb31fe865effdd3b17e27b64964826fc24ca5e71871097b2472b49499a538b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":21,"fee_ok":14,"fee_bad":0,"fee_unchecked":7,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0415.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0415.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0415$t$, $t$Gloucester Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District #1 (Glendora area): issued by Gloucester Township Fire District #1 Bureau of Fire Prevention (Glendora Fire Company) (fire district). Check the property's fire district in the 'Special Taxing Districts' block at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #1 (Glendora area) contact: 856-939-1177 · gtfm81@comcast.net","Fire District #1 (Glendora area), apply: 10 or more business days before settlement for the lowest fee","Fire District #1 (Glendora area), how to apply: Download the District 1 smoke application (08-2025 version) from the district's forms page, and mail it with cash or check payable to GTFD1 to PO Box 38, Glendora, NJ 08029. Fees are based on business days.","Fire District #2 (Chews Landing area): issued by Gloucester Township Fire District #2 Bureau of Fire Prevention (Chews Landing Fire Department) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #2 (Chews Landing area) contact: 856-282-3370 ext. 124 · gtfm82@gtfd2.com","Fire District #2 (Chews Landing area), apply: 10 or more business days before settlement (not counting settlement day) for the lowest fee","Fire District #2 (Chews Landing area), how to apply: Download the application (Word file) from the Fire Prevention Bureau page, fill it in (include lockbox code if vacant), and submit it with exact cash or a check payable to GTFD#2 to 43 Somerdale Road, Blackwood, NJ 08012 (fax 856-545-7485, email gtfm82@gtfd2.com). Appointments are given as a two-hour window. Call the Fire Prevention Office to schedule a re-inspection after a failure.","Fire District #3 (Blenheim area): issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (for Gloucester Township Fire District #3, Blenheim) (NJ DCA, state). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #3 (Blenheim area) contact: 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Fire District #3 (Blenheim area), apply: More than 10 business days before closing for the lowest fee","Fire District #3 (Blenheim area), how to apply: Apply online through the DCA Fire Safety portal ('Apply For Smoke Certification'). The applicant checks off each placement and operating requirement, pays by e-check or credit card before submitting, and the certificate is emailed once the fee is paid and any required inspections are done. A valid email address is required. Electric-heat homes with no CO requirement should email BFCE_CSDCMAC@dca.n","Fire District #4 (Blackwood area): issued by Gloucester Township Fire District #4 Bureau of Fire Prevention (Blackwood Fire Company) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #4 (Blackwood area) contact: 856-227-7037 · fm84@gtfd4.org","Fire District #4 (Blackwood area), apply: 10 or more business days before settlement for the lowest fee","Fire District #4 (Blackwood area), how to apply: Download the Smoke Detector/CO application, and mail it with cash or check payable to GTFD4 to 14 West Central Avenue, Blackwood, NJ 08012. To schedule, email fm84@gtfd4.org or call 856-227-7037 with the address, preferred dates and a contact phone. Office hours Monday to Thursday 8 am to 4 pm.","Fire District #5 (Lambs Terrace / Sicklerville area): issued by Gloucester Township Fire District #5 Bureau of Fire Prevention (Lambs Terrace Fire Company) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #5 (Lambs Terrace / Sicklerville area) contact: 856-228-0678","Fire District #5 (Lambs Terrace / Sicklerville area), apply: 10 or more business days before settlement for the lowest fee","Fire District #5 (Lambs Terrace / Sicklerville area), how to apply: Download the Smoke Application from the district's Forms & Applications page and mail it with cash or check payable to GTFD5 to 1781 Sicklerville Rd., Sicklerville, NJ 08081 (fax 856-374-0424).","Fire District #6 (Erial area): issued by Gloucester Township Fire District No. 6 Bureau of Fire Prevention (Erial) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #6 (Erial area) contact: 856-435-0700 · Inspections@gtfd6.com","Fire District #6 (Erial area), apply: 10 or more business days before settlement for the lowest fee; affidavits are processed once a week","Fire District #6 (Erial area), how to apply: For a sale, the owner or agent completes and signs the district's CSACMAPFEC affidavit (self-certification in lieu of inspection under N.J.A.C. 5:70-2.3(b)) and emails it to Inspections@gtfd6.com or drops it off at 1946 Williamstown-Erial Road, Sicklerville (mailbox if no one is there). Pay by cash or check payable to GTFD6; no certificate until paid. Affidavits are processed once a week. Rentals ","Fire official in the NJ state directory (fire district), updated 6/25/2025: Brandon O'Connor · (856) 227-7731 · fm84@gtfd4.org","Fire official in the NJ state directory (NJ DCA, state), updated 2/9/2026: Louis Kilmer · (609) 633-6132","Fire official in the NJ state directory (fire district), updated 3/16/2026: Kenneth Young · (856) 282-3370 · gtfm82@gtfd2.com","Districts 1, 2, 4 and 5: CO alarms must be less than 7 years old","Districts 1, 4 and 5: smoke alarms older than 10 years not accepted; battery alarms must be 10-year sealed (hardwired exempt); hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms within 10 feet of all bedroom doors","House numbers at least 4 inches high, contrasting color, permanently on the house and visible from the street (mailbox or light post numbers not accepted)","Homes with a secondary power source (solar, generator, battery storage) need a non-handwritten 'CAUTION: MULTIPLE SOURCES OF POWER' label within 18 inches of the main electrical panel and the electric meter","District 5 checklist: alarm type follows the year the house was built (for example 1991 to present: hardwired interconnected alarms with battery backup on every level and in each bedroom)","Current 2025-2026 district forms do not list a fire extinguisher (District 6's 2026 affidavit title still says 'Portable Fire Extinguisher' but its checklist has no extinguisher item)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District #1 (Glendora area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #1 (Glendora area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #1 (Glendora area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #1 (Glendora area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #2 (Chews Landing area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #2 (Chews Landing area): 5 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #2 (Chews Landing area): 4 or fewer business days before settlement (done as manpower permits)","amount":"$125.00"},{"label":"Fire District #3 (Blenheim area): More than 10 business days before closing","amount":"$45"},{"label":"Fire District #3 (Blenheim area): 4 to 10 business days before closing","amount":"$90"},{"label":"Fire District #3 (Blenheim area): Less than 4 business days before closing","amount":"$161"},{"label":"Fire District #4 (Blackwood area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #4 (Blackwood area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #4 (Blackwood area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #4 (Blackwood area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #6 (Erial area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #6 (Erial area): 4 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #6 (Erial area): Fewer than 4 business days before settlement","amount":"$125.00"}]$j$::jsonb, $t$https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453$t$, $t$https://glotwpnjfd1.gov/district-forms$t$, $j$[{"url":"https://glotwp.com/department/fire-departments/","label":"Official source (glotwp.com)"},{"url":"https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453","label":"Official source (img1.wsimg.com)"},{"url":"https://gtfd2.org/?page_id=4","label":"Official source (gtfd2.org)"},{"url":"https://gtfd2.org/wp-content/uploads/2025/04/Application-CO-Insp.docx","label":"Official source (gtfd2.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://gtfd4.org/fire-prevention","label":"Official source (gtfd4.org)"}]$j$::jsonb, $t$The Township of Gloucester is served by six separate Boards of Fire Commissioners, known as Gloucester Township Fire District #1 through Gloucester Township Fire District #6$t$, $t$514046ae4899306500ca0a05c8d62f2dbc9b08a8ffa40cfca18a021bcf37d4c2$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":21,"fee_ok":14,"fee_bad":0,"fee_unchecked":7,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0415.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0415.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC) / Temporary Certificate of Compliance (TCOC), Residential Resale Inspection (Township Code Chapter 186)$t$, $j$["Issued by: Construction & Zoning Office / Code Official (Township Annex, 10 Reeve Ave.)","Contact: 856-833-6265 · rsheppard@haddontwp.com","Apply: Application in and paid at least 14 business days before closing; inspections Mondays and Wednesdays 8 to 10 AM","How to apply: Download the Residential Resale / Tenant Change Inspection Application (PDF) or use the township's online GovPilot form (https://main.govpilot.com/web/public/474cdd15-dbc_Rental-Resale-Township-of-Haddon?uid=7071&ust=NJ&pu=1&id=0). Submit it with a check or money order payable to 'Township of Haddon' to the Annex Building, 10 Reeve Ave., at least 14 business days before closing. Questions: Ryan Sh","Valid for: 6 months (if the sale does not happen within 6 months a new application, fee and inspection are required)","Interior and exterior inspection under the township Land Use code, International Property Maintenance Code and NJ fire code; includes the smoke/CO (CSDCMAC) check","House numbers: numerals only, at least 4 inches, contrasting color, on the house (not doors or mailboxes)","Smoke alarms on every level on the ceiling, at the base of basement stairs, within 10 feet of all bedrooms; no more than 10 years old; 10-year sealed battery where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedrooms, less than 10 years old","Thumb-turn locks on all exit doors; no keyed locks on the egress side","Gutters, downspouts with splash blocks, roof, soffit, fascia, siding and paint in good repair","Guardrails on porches, decks and landings over 30 inches; handrails on steps with 3 or more risers","Sidewalk, driveway and apron level with no trip hazards; replacement rather than patching","GFCI outlets trip; outlet, switch and junction box covers in place; electrical panel covered, no open spaces, circuits labeled","Faucets hot on left, cold on right, no leaks; sink strainers; stove anti-tip device","Sump pump discharges outside, not into the sanitary sewer; water meter installed and accessible","Metal dryer vent; proper water heater and furnace venting; water heater bonding; oil heat emergency shut-off switch with red label","Attached garage walls/ceiling next to living space drywalled and taped","Bathroom window or working exhaust fan; screens installed","Pool barrier 5 to 6 feet with self-closing, self-latching gate","Also: Open permits must be closed: Any work that needed a permit must have had one, with final inspections done and a Certificate of Approval issued.","Also: Water meter: Water meter must be installed, connected and accessible at inspection."]$j$::jsonb, $j$[{"label":"COC application more than 14 business days before change of ownership","amount":"$150"},{"label":"COC application more than 7 but less than 13 business days before","amount":"$175"},{"label":"COC application more than 4 but less than 6 business days before","amount":"$200"},{"label":"COC application less than 4 business days before","amount":"$225"},{"label":"COC application after the change of ownership","amount":"$250"},{"label":"Re-inspection (paid before re-inspection is scheduled)","amount":"$25.00"},{"label":"First re-inspection after a Temporary COC","amount":"$25"},{"label":"Second re-inspection after a Temporary COC","amount":"$50"},{"label":"Third re-inspection after a Temporary COC","amount":"$75"},{"label":"Fourth or later re-inspection after a Temporary COC, each","amount":"$100"}]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/construction-office/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.haddontwp.com/departmets/construction-office/","label":"Official source (haddontwp.com)"}]$j$::jsonb, $t$A Residential Property Inspection MUST be completed and a COC or Temporary COC MUST be issued PRIOR to closing per Township of Haddon Municipal Code Chapter 186-6 Article 3B.$t$, $t$21c228627b9c264ed23dca524d57da5882e194e07a5304dcd9abd453642160c4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":6,"q_ok":2,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Township Construction & Zoning Office / Code Official (smoke and CO check done as part of the township Resale COC inspection) (town fire bureau)","Contact: 856-833-6265 · rsheppard@haddontwp.com","Apply: At least 14 business days before closing","How to apply: No separate smoke certificate application or fee was found. The Residential Resale / Tenant Change Inspection Application covers the smoke/CO (CSDCMAC) check together with the COC; see the resale_co fees ($150 and up).","Fire official in the NJ state directory (town), updated 5/19/2026: William A Behnke · (856) 854-1176 · wbehnke@haddontwp.com;","Smoke alarms no more than 10 years old; 10-year sealed battery units where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarms less than 10 years old, in the hallway within 10 feet of all bedrooms","Homes with a low-voltage fire alarm system must have it tested by a certified alarm contractor before the inspection and show the certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/construction-office/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I understand that any change of ownership/occupancy including storage of personal property may not occur, prior to successful inspection & possession of a (CSDCMAC) inspection.$t$, $t$42d150424d31ea911b08b790f27cf5599ac03f9a67a40e07f36785253c918f1b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":6,"q_ok":2,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale CO (made up of the Fire Marshal smoke detector certificate of compliance plus the sidewalk inspection certificate of compliance)$t$, $j$["Issued by: Borough of Haddonfield Construction and Zoning Office (Community Development), with the Bureau of Fire Prevention (Fire Marshals) and the Sidewalk Inspector","Contact: 856-429-4700 · SKrohn@haddonfield-nj.gov","Apply: Notify the Borough at least 30 days before transfer of title (or within 5 days of signing the sales contract, whichever is later) for the sidewalk inspection. Lower fees apply if applications are submitted more than 10 business days before settlement.","How to apply: Submit the Smoke Detector form, Sidewalk Inspection form and (if in the Historic District) the Historic District Disclosure form to the Construction and Zoning Office, Room 104, Borough Hall, 242 Kings Highway East, with the fees in cash or check payable to the Borough of Haddonfield. Staff check permit history first. Schedule the smoke inspection directly with the Fire Marshal. Sidewalk inspectio","Valid for: 90 days","All construction permits must be inspected and closed before the CO is released","Sidewalks, driveway aprons and walkways in the public right-of-way free of trip hazards (no lifts, holes or height differences of 1/2 inch or more)","Sidewalk repairs completed and the Borough notified at least 7 days before title transfer, or money placed in escrow and repairs done within 30 days after closing","Smoke alarm on every level (10-year sealed battery if battery powered)","CO alarm outside the bedroom area","ABC portable fire extinguisher no larger than 10 lb, within 10 feet of the kitchen","Street number at least 4 inches, contrasting and readable from the street","Historic District disclosure form if the home is in the Historic District","Also: Open construction permits must be closed: Staff check permit history; all permits must be inspected and closed before the Resale CO is released, and no smoke inspection is scheduled while permits are open.","Also: Sidewalk and driveway apron inspection: Required on every sale; repairs or escrow before closing.","Also: Historic District disclosure: Buyers must be notified if the property is in the Historic District (Ch. 135-60). No fee.","Also: Move-out/move-in trash pickup: Schedule with Public Works at 856-429-0183 before putting out excess trash."]$j$::jsonb, $j$[{"label":"Sidewalk inspection, settlement more than 10 business days away (includes first re-check after repairs)","amount":"$50"},{"label":"Sidewalk inspection, settlement less than 10 business days away","amount":"$75"},{"label":"Sidewalk re-inspection, each (beyond the first re-check)","amount":"$25.00"},{"label":"Sidewalk late notice fee, each failure to give timely notice","amount":"$25.00"},{"label":"Historic District Disclosure Form","amount":"no fee"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071$t$, $t$https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$Selling a Home in the Borough of Haddonfield Resale CO 1. Smoke Detector Form / Fire Marshall CO Inspection$t$, $t$f19ebe81600d001f8b347a88ce62d082c3f604bd1314eb6dced74b53072d4e94$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Haddonfield Bureau of Fire Prevention (Office of the Fire Marshal) (town fire bureau)","Contact: 856-429-4308 ext. 504/505 · EBusch@haddonfield-nj.gov","Apply: Lowest fee if submitted more than 10 business days before settlement","How to apply: Submit the Sale and Rental of Residential Property Ordinance Compliance Application with payment (cash or check to the Borough of Haddonfield) at the Construction and Zoning Office, Room 104, Borough Hall. Then schedule directly with the Fire Marshal's Office; inspections are Tuesdays or Wednesdays, 9 a.m. to 1 p.m. If it passes, a copy of the approval is left on site.","Fire official in the NJ state directory (town), updated 5/18/2026: Ernest F Busch · (856) 429-4308 · ebusch@haddonfield-nj.gov","All single-station battery smoke alarms must be the 10-year sealed battery type","Hardwired (110-volt) smoke detectors maintained per manufacturer and the code in effect at installation","ABC-type extinguisher, no larger than 10 lb, within 10 feet of the kitchen area","Street number at least 4 inches, contrasting, readable from the street","Form includes a check for a secondary power source","No inspection is scheduled until all open permits are closed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Submitted more than 10 business days before settlement","amount":"$56"},{"label":"Submitted 4 to 10 business days before settlement","amount":"$125"},{"label":"Submitted fewer than 4 business days before settlement","amount":"$201"},{"label":"First re-inspection","amount":"no additional charge"},{"label":"Each additional re-inspection (prepaid)","amount":"$25"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260616113807071$t$, $t$https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Resale%20Rental%20CO%20App%20-%20Smoke%20Detector%20Application%20Form%20-%20Updated%20Fees%20-%20May%202026.pdf?t=20260616113807071","label":"Official source (haddonfieldnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Borough of Haddonfield, Bureau of Fire Prevention is responsible for inspection of all one- and two-family dwelling units.$t$, $t$60c44c0a7d2cdce1602bf9f31bb6cb884de6eea19a1435dc8603279ec9e13d7c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) / Certificate of Compliance$t$, $j$["Issued by: Zoning Officer / Code Enforcement Officer (Zoning and Code Enforcement)","Contact: 856-546-2580 · zoning@haddonhts.com","Apply: No application can be filed without a settlement date. All fees must be paid before scheduling an inspection.","How to apply: Fill out the CCO application (needs a settlement date) and return it with payment (check or cash) to Zoning and Code Enforcement, 514 W. Atlantic Avenue, Haddon Heights. The applicant is responsible for scheduling all inspections and re-inspections after fees are paid."]$j$::jsonb, $j$[{"label":"Application filing fee","amount":"$11.00"},{"label":"First inspection","amount":"$50.00"},{"label":"Second inspection","amount":"no charge"},{"label":"Third or later inspection, each","amount":"$25.00"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO$t$, $t$https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy$t$, $j$[{"url":"https://www.haddonhts.com/1364/Certificate-of-Continued-Occupancy","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3128/Certification-of-Continued-Occupancy-Application-CCO","label":"Official source (haddonhts.com)"}]$j$::jsonb, $t$Per Ordinance 2018:1453, no residential properties may change ownership or tenancy until a Certificate of Continued Occupancy (CCO) is issued by the Zoning Officer and a Smoke Detector/Carbon Monoxide Inspection is also required by the Fire Department.$t$, $t$3663657cffb47e211b142bba1e7ebc0213b8fce435cdbb6ad60dc86a7a39f2fc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0418$t$, $t$Haddon Heights Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Heights Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: 856-546-7135 ext. 81","Apply: Lowest fee with 8 or more days advance notice; schedule early","How to apply: Fill out the Request for Inspection form and email it to one of the fire inspectors, fax it to 856-546-5340, or bring it to the office at 608 Station Avenue. Checks payable to Borough of Haddon Heights.","Fire official in the NJ state directory, updated 7/22/2026: Benjamin Zwaska · (856) 546-7135 · bzwaska@haddonhts.com","One smoke detector on each level including basement and any attic reachable by stairs; each level of each unit in a two-family","Ceiling-mounted at least 4 inches from walls, at least 36 inches from cold air returns and bathroom doors, away from ceiling fans; wall-mounted 4 to 12 inches below ceiling","UL-approved CO detector in the vicinity of each sleeping area","House number visible from the street, Arabic numerals at least 3 inches","2-A:10-B:C extinguisher no more than 10 lbs, charged, in a conspicuous place no more than 10 feet from the kitchen, instructions visible","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"8 or more days advance notice","amount":"$75.00"},{"label":"4 to 7 days advance notice","amount":"$100.00"},{"label":"3 or fewer days advance notice","amount":"$140.00"},{"label":"Re-inspection","amount":"$35.00"}]$j$::jsonb, $t$https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB$t$, $t$https://www.haddonhts.com/1336/Fire-Prevention$t$, $j$[{"url":"https://www.haddonhts.com/1336/Fire-Prevention","label":"Official source (haddonhts.com)"},{"url":"https://www.haddonhts.com/DocumentCenter/View/3225/Request-for-Smoke-Detector-and-Carbon-Monoxide-Inspection-3207-KB","label":"Official source (haddonhts.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SELLING YOUR HOME? The Bureau of Fire Prevention also handles the Certificate of Smoke Detector and Carbon Monoxide Compliance (CSDCMAC). This inspection is required prior to selling your home.$t$, $t$3cb3fa2b971ba2a11ef440ebb6cceb341e8057c9463ebfc1c0b7ab7c6dc1e65f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0418.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0418.json$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Watchdog could not confirm online whether Hi-Nella Borough requires a resale certificate. Call the office before closing.","Contact: 856-784-6237 ext. 400 · clerkhinellaboro@comcast.net"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.hinellaboro.org/contact$t$, $j$[{"url":"https://www.hinellaboro.org/contact","label":"Official source (hinellaboro.org)"}]$j$::jsonb, $t$Construction DCA (609) 567-3653$t$, $t$ab3534a705d0c6f0b401ca33fe791462b9edd314315b979beba46a0a152b7003$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0419$t$, $t$Hi-Nella Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Regional Fire Prevention Alliance (Borough of Barrington Bureau of Fire Prevention) (town fire bureau)","Contact: 856-547-0991 · firealliance@barringtonboro.com","Apply: Lowest fee with 14 or more business days notice before the change of occupant (weekends, holidays and the settlement date do not count)","How to apply: Fill out the Alliance's certificate application and email it to firealliance@barringtonboro.com, or print it and drop it in the mailbox or mail it to 205 Haines Avenue, Barrington, NJ 08007. A check or money order payable to 'Regional Fire Prevention Alliance' must go with the application. Fees are non-refundable.","Fire official in the NJ state directory (town), updated 5/18/2026: Nicholas D'Alonzo · (856) 547-0991 · ndalonzo@barringtonboro.com","All smoke alarms (hardwired and battery) must be less than 10 years old; take them down and check the date, replace if undated","Smoke alarm type by build year: pre-1975 homes need 10-year sealed battery alarms on each level; newer homes need hardwired, interconnected alarms per the year-built chart","Smoke alarm in each sleeping area plus one outside each sleeping area within 10 feet (local ordinance 172-8 B)","CO alarm outside of and near all sleeping areas if there is a fuel-burning appliance, fireplace or garage; CO alarms must be less than 7 years old","Low-voltage alarm systems must be tested by an alarm contractor before the inspection, with the certificate shown to the inspector","House numbers: Arabic numerals at least 3 inches, contrasting, at least 60 inches above ground, visible from the street","Homes with a secondary power source (solar, generator, battery storage) need a printed label within 18 inches of the main panel and meter, like \"CAUTION MULTIPLE SOURCES OF POWER\"","Fire extinguisher (June 2025 form): fully charged 2-A:10-BC in or within 10 feet of the kitchen, visible, mounted no higher than 5 feet, and either under 1 year old or tagged by a NJ certified fire equipment contractor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14+ business days before change of occupant","amount":"$66.00"},{"label":"Request received 8 to 13 business days before","amount":"$74.00"},{"label":"Request received 4 to 7 business days before","amount":"$106.00"},{"label":"3 business days or less notice","amount":"$171.00"},{"label":"Re-inspection after a failed inspection","amount":"$50.00"}]$j$::jsonb, $t$https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf$t$, $t$https://barringtonboro.com/regional-fire-prevention-alliance/$t$, $j$[{"url":"https://barringtonboro.com/regional-fire-prevention-alliance/","label":"Official source (barringtonboro.com)"},{"url":"https://barringtonboro.com/wp-content/uploads/2025/11/Barrington-Smoke-Doc-update-Fillable-pdf.pdf","label":"Official source (barringtonboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Regional Fire Prevention Alliance of Barrington, New Jersey serves the Municipalities of Barrington, Hi-Nella, Lawnside, Mt. Ephraim and Oaklyn.$t$, $t$59dd7f0268d4cb1bcb1bc20437e326ed24931446e748cf3a3e991101f3aea4ad$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0419.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0419.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Property Compliance (CPC)$t$, $j$["Issued by: Borough of Laurel Springs Office of Property Maintenance and Fire Prevention (Property Maintenance Officer / public officer)","Contact: 856-784-0500 · dkrawchuk@laurelsprings-nj.com","Apply: Notify at least 10 days before the change in occupancy; higher fees for 4 to 9 days and 1 to 3 days notice","How to apply: Fill out the Certificate of Property Compliance form (and the Fire Safety Certificate form for a sale) and pay at Borough Hall, 723 West Atlantic Avenue, payable to the Borough of Laurel Springs. Inspectors are notified by email only after payment is received. Fees are non-refundable. The inspector leaves a copy at the property.","Valid for: 45 days from the date of inspection","No refuse, garbage, abandoned vehicles, or overgrown brush, weeds or trees","Sidewalks and driveways free of holes; no standing stormwater","Foundation, walls, chimney, roof shingles and gutters in good repair","Porches, landings, stairs, balconies and railings safe","No broken glass or doors; windows and doors working","Working smoke detectors and CO detector","Central heating, air conditioning, kitchen, baths and light fixtures in working order","No fire or electrical hazards","Basement and crawl space condition","Property tax, sewer and property code fee balances are checked by Borough staff","Also: Tax, sewer and code fee balances checked: Borough Hall staff record property tax, sewer utility fee and property code fee status on the CPC form.","Also: Lead-safe certificate question: The CPC form asks whether the owner has a valid lead-safe certificate."]$j$::jsonb, $j$[{"label":"CPC, home resale, 10+ days notice","amount":"$50"},{"label":"CPC, home resale, 4 to 9 days notice","amount":"$70"},{"label":"CPC, home resale, 1 to 3 days notice","amount":"$125"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance$t$, $t$https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/389/Certificate-of-Property-Compliance","label":"Official source (laurelsprings-nj.com)"}]$j$::jsonb, $t$Whenever there shall occur a change in occupancy in any residential property, including one- and two-family homes and apartments, a new certificate of property compliance shall be required. A change in occupancy shall occur in an apartment by a change in tenant or by the execution of a new lease with a new tenant, and in all other dwelling units by sale or lease.$t$, $t$88d9df4d8c4f93b401c6500c514579c4a367ab71a5844c9eccc6f18959f87f8a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0420$t$, $t$Laurel Springs Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Laurel Springs Office of Fire Prevention and Property Maintenance (Fire Marshal) (town fire bureau)","Contact: 856-784-0500 ext. 25 · kcheeseman@laurelsprings-nj.com","Apply: Ten days notice is required for all inspections","How to apply: Fill out the Fire Safety Certificate of Compliance form and pay at Borough Hall (payable to the Borough of Laurel Springs) together with the CPC. The Fire Marshal is notified by email after payment.","Fire official in the NJ state directory, updated 5/22/2026: Kenneth Cheeseman · (856) 784-0500 · kcheeseman@laurelsprings-nj.com","Working smoke alarms on every level including basement and within 10 feet of bedroom doors; type depends on build year (hardwired and interconnected for newer homes, in every bedroom for 1991/1992 and later)","Hardwired smoke detectors may not be replaced with battery units; interconnected detectors must be replaced with compatible ones","Basement detector within 10 feet of the stairway, not in the stairway","Two-family homes: detectors at each landing of common hallways and stairs","Do not place detectors within 5 feet of a kitchen, 3 feet of fans, bathroom doors or supply vents, or 1 foot of a light fixture; detectors must not be painted","Central-station monitored alarm systems must be certified by a licensed NJ Fire Protection Contractor before the Fire Marshal's inspection","CO alarm on each sleeping level, in the hallway near every bedroom door, if there is a fuel-burning appliance or attached garage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Safety Inspection, home resale, 10+ days notice","amount":"$45"},{"label":"Fire Safety Inspection, home resale, 4 to 9 days notice","amount":"$90"},{"label":"Fire Safety Inspection, home resale, 1 to 3 days notice","amount":"$161"}]$j$::jsonb, $t$https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF$t$, $t$https://www.laurelsprings-nj.com/1359/Fire-Safety-Requirements-Smoke-Detectors$t$, $j$[{"url":"https://www.laurelsprings-nj.com/1213/Fire-Prevention-Property-Maintenance","label":"Official source (laurelsprings-nj.com)"},{"url":"https://www.laurelsprings-nj.com/DocumentCenter/View/390/Fire-Safety-Certificate-of-Compliance-PDF","label":"Official source (laurelsprings-nj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In the case of the resale of a property, both a Certificate of Property Compliance and Fire Safety are required.$t$, $t$19efa60a462214b186fe7bf469811e3bab49670ac3f62e7e3f74e913a2535b6d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0420.json$t$, true),
  ($t$0421$t$, $t$Lawnside Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Resale / Rental)$t$, $j$["Issued by: Borough of Lawnside Construction Office (Construction Code Department)","Contact: 856-573-6214 · m.hauser@lawnside.net","Apply: Allow 10 business days for the inspection to be completed","How to apply: Fill out the Certificate of Occupancy Application (circle Resale) and submit it to the Construction Office, 4 Dr. Martin Luther King Jr. Road, with $75 per unit in cash, check or money order. Choose pick up, fax or email for the certificate. Repairs must be done within 30 days of the first inspection or a new application is needed.","Working smoke alarm on each level and in every bedroom","CO alarm within 10 feet of sleeping areas","ABC extinguisher (2.5 lb) mounted within 10 feet of the cooking area","Heater and roof certification from a NJ licensed contractor (resale only); a private home inspection or a new roof or heater under permit in the last 5 years is accepted instead","Heater/chimney connection secure; water heater relief valve pipe 2 to 6 inches from the floor","Sump pump may not discharge into the sewer line","Sidewalks and walkway to the house in good condition with no trip hazards","Graspable handrails on steps 24 inches or more above grade (both sides if 44 inches or wider); guardrails on decks and porches 24 inches or more above grade","GFCI outlets within 6 feet of sinks and along kitchen counters; all outlet and switch covers in place; no openings in the breaker panel","No water leaks; faucets working","Holes in walls and floors fixed; exposed wood painted inside and out","Trash and debris removed","House numbers visible from the street","All open construction permits completed and closed; no unresolved violation notices","Also: Open permits must be closed: All work under open construction permits must be completed and permits closed before the CO is issued.","Also: Heater and roof certification (resale only): From a NJ licensed contractor, or a private home inspection, unless a new roof or heater was installed under a UCC permit in the last 5 years."]$j$::jsonb, $j$[{"label":"CO inspection, per unit (includes initial inspection and one re-inspection)","amount":"$75.00"},{"label":"Additional re-inspection (after the included re-inspection, a missed re-inspection, or violations not fixed within 30 days)","amount":"$75.00"},{"label":"Fine for violations not corrected within 30 days, per day","amount":"$25"}]$j$::jsonb, $t$https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF$t$, $t$https://www.lawnside.net/1204/Construction-Department$t$, $j$[{"url":"https://www.lawnside.net/DocumentCenter/View/412/Certificate-of-Occupancy-Application-PDF","label":"Official source (lawnside.net)"}]$j$::jsonb, $t$NOTE: This Dwelling Is Not To Be Occupied Until A Cerificate Of Occupancy Is Issued By The Construction Code Department Of The Borough Of Lawnside.$t$, $t$42984f77564966f84d43f42d18881e703ca033e25a58b54acd66be65c6639e2a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0421.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0421.json$t$, true),
